mod solution;

fn main() {
    let cases = [
    (r#"[7,2,5,4,9]"#, r#"7,5,9"#),
    (r#"[1,6,5]"#, r#"6,5"#),
    (r#"
[1,6,5]
"#, r#"6,5"#),
    (r#"  
[7,2,5,4,9]
  "#, r#"7,5,9"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS same-direction");
}
